#!/usr/bin/env python3
"""Publish the bundled native catalogue to the file:// browser preview without CORS."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[1]
catalog = json.loads((root / "assets/wallpapers/catalog.json").read_text())
entries = [{"title": item["title"], "file": "../assets/wallpapers/" + item["file"],
            "sourcePage": item["sourcePage"]} for item in catalog["wallpapers"]]
(root / "preview/wallpapers.js").write_text(
    "// Generated by tools/sync_wallpapers.py from the native asset catalogue.\n"
    "window.WALLPAPERS = " + json.dumps(entries, indent=2) + ";\n"
    "window.TVMAZE_SHOWS = " + (root / "assets/wallpapers/tvmaze-shows.json").read_text().strip() + ";\n")
